shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-subtle: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c2b2;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --navy-bg: #0f1d2b;
    --navy-card: #16283b;
    --navy-line: #294057;
    --slate-blue: #2b547e;
    --dissent-bg: #f1ede4;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  /* Strict Bilingual Visibility Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: 'Lora', 'Noto Serif SC', Georgia, serif;
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.85;
    overflow-x: hidden;
  }

  /* Progress Indicator */
  .progress-rail {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: transparent;
    z-index: 1001;
  }
  .progress-fill {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s linear;
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.75rem 1.5rem;
  }
  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }
  .brand-cluster {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
  }
  .wsj-monogram {
    font-family: 'Playfair Display', serif;
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    border-right: 1px solid var(--line-strong);
    padding-right: 0.85rem;
  }
  .rubric-pill {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.73rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    background: var(--accent-soft);
    padding: 0.22rem 0.6rem;
    border-radius: 2px;
  }
  .edition-meta {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.72rem;
    color: var(--muted);
  }
  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--line-strong);
    border-radius: 3px;
    overflow: hidden;
    background: var(--paper-card);
  }
  .lang-btn {
    border: none;
    background: transparent;
    padding: 0.32rem 0.75rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.76rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.18s ease;
  }
  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero-header {
    max-width: 1180px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 2px solid var(--ink);
  }
  .hero-kicker-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.9rem;
    margin-bottom: 1.25rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
  }
  .hero-column-tag {
    font-weight: 700;
    font-size: 0.8rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--accent);
  }
  .hero-kicker-sep {
    color: var(--line-strong);
  }
  .hero-section-tag {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.78rem;
    color: var(--muted);
  }
  .hero-title {
    font-family: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    font-weight: 800;
    font-size: clamp(2.15rem, 4.4vw, 3.65rem);
    line-height: 1.16;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 1.35rem;
    max-width: 960px;
  }
  :host([lang="zh-CN"]) .hero-title {
    line-height: 1.25;
    letter-spacing: 0.01em;
  }
  .hero-dek {
    font-family: 'Lora', 'Noto Serif SC', serif;
    font-size: clamp(1.08rem, 1.6vw, 1.28rem);
    line-height: 1.68;
    color: var(--muted);
    max-width: 840px;
    margin-bottom: 2rem;
  }
  .byline-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    padding-top: 1.15rem;
    border-top: 1px solid var(--line);
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.85rem;
    color: var(--muted);
  }
  .byline-authors strong {
    color: var(--ink);
    font-weight: 600;
  }
  .byline-timestamp {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.78rem;
  }

  /* Main Container */
  .article-shell {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2.75rem 1.5rem 5rem;
  }

  /* Two-Column Editorial Grid */
  .editorial-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(260px, 360px);
    justify-content: space-between;
    gap: 3rem;
    align-items: start;
  }

  /* Prose Styling */
  .prose-stream {
    width: 100%;
  }
  .prose-p {
    font-size: 1.125rem;
    line-height: 1.9;
    color: var(--body);
    margin-bottom: 1.55rem;
  }
  :host([lang="en"]) .prose-p {
    font-family: 'Lora', Georgia, serif;
    font-size: 1.11rem;
    line-height: 1.84;
  }
  :host([lang="zh-CN"]) .prose-p {
    font-family: 'Noto Serif SC', serif;
    font-size: 1.13rem;
    line-height: 1.96;
    letter-spacing: 0.015em;
  }

  /* Lead Paragraph Treatment (No CSS ::first-letter on Chinese) */
  .lead-p {
    font-size: 1.24rem !important;
    line-height: 1.85 !important;
    color: var(--ink);
    font-weight: 600;
    border-left: 3px solid var(--accent);
    padding-left: 1.2rem;
    margin-bottom: 1.85rem;
  }

  /* Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 0.12em;
    font-weight: 600;
    border-radius: 1px;
  }

  /* Sidebar Rail */
  .sidebar-rail {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    position: sticky;
    top: 4.75rem;
  }
  .sidebar-card {
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-top: 3px solid var(--ink);
    padding: 1.35rem 1.4rem;
  }
  .sidebar-card-kicker {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 0.65rem;
  }
  .sidebar-card-title {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.98rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.75rem;
    line-height: 1.4;
  }
  .sidebar-stat-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding: 0.55rem 0;
    border-bottom: 1px dashed var(--line-strong);
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.85rem;
  }
  .sidebar-stat-row:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }
  .sidebar-stat-val {
    font-family: 'JetBrains Mono', monospace;
    font-weight: 700;
    font-size: 0.95rem;
    color: var(--ink);
  }
  .sidebar-stat-val.accent {
    color: var(--accent);
  }

  /* Quantitative Survey Showcase (Full-Bleed within Container) */
  .quant-showcase {
    margin: 3.25rem 0;
    background: var(--navy-bg);
    color: #f4f1ea;
    border-radius: 4px;
    padding: 2.5rem 2.25rem;
    border-top: 4px solid var(--accent);
    box-shadow: 0 16px 36px rgba(15, 29, 43, 0.14);
  }
  .quant-header {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1.25rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid var(--navy-line);
    margin-bottom: 1.85rem;
  }
  .quant-kicker {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #f0944d;
    margin-bottom: 0.45rem;
  }
  .quant-title {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: clamp(1.38rem, 2.4vw, 1.85rem);
    font-weight: 700;
    color: #ffffff;
    line-height: 1.3;
  }
  .quant-subtitle {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.88rem;
    color: #b7c4d1;
    margin-top: 0.35rem;
  }
  .quant-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 1.25rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.8rem;
    color: #d6e0ea;
  }
  .legend-item {
    display: flex;
    align-items: center;
    gap: 0.45rem;
  }
  .legend-swatch {
    width: 12px;
    height: 12px;
    border-radius: 2px;
  }
  .swatch-oct { background: #f08c43; }
  .swatch-jul { background: #5a7d9f; }

  /* Derived Metrics Grid (m1, m2, m3) */
  .metrics-trio {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.25rem;
    margin-bottom: 2rem;
  }
  .metric-card {
    background: var(--navy-card);
    border: 1px solid var(--navy-line);
    padding: 1.25rem 1.35rem;
    border-radius: 3px;
  }
  .metric-val {
    font-family: 'JetBrains Mono', monospace;
    font-size: 1.38rem;
    font-weight: 700;
    color: #f0944d;
    margin-bottom: 0.45rem;
    line-height: 1.25;
  }
  .metric-lbl {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.84rem;
    font-weight: 600;
    color: #ffffff;
    margin-bottom: 0.35rem;
    line-height: 1.4;
  }
  .metric-note {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.74rem;
    color: #9bb0c4;
    line-height: 1.45;
  }

  .svg-chart-wrap {
    width: 100%;
    background: rgba(10, 20, 31, 0.55);
    border: 1px solid var(--navy-line);
    border-radius: 3px;
    padding: 1.25rem 1rem 0.85rem;
  }
  .quant-footnote {
    margin-top: 1rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.76rem;
    color: #8fa4b8;
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  /* Thematic Section Divider */
  .section-divider {
    margin: 3.25rem 0 2rem;
    padding-top: 1.5rem;
    border-top: 2px solid var(--ink);
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 1rem;
    flex-wrap: wrap;
  }
  .section-num {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 0.1em;
    text-transform: uppercase;
  }
  .section-heading {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: clamp(1.4rem, 2.2vw, 1.8rem);
    font-weight: 700;
    color: var(--ink);
    line-height: 1.3;
  }

  /* Derived Pull Quote (q1) */
  .pull-quote {
    margin: 2.25rem 0;
    padding: 1.65rem 1.85rem;
    background: var(--paper-card);
    border-left: 4px solid var(--accent);
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
  }
  .pull-quote .quote-text {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.22rem;
    font-weight: 700;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 0.75rem;
  }
  .pull-quote .quote-attrib {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Fiscal & AI Comparison Panel */
  .fiscal-comparison-panel {
    margin: 2.25rem 0;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.75rem;
  }
  .panel-header {
    margin-bottom: 1.25rem;
    padding-bottom: 0.85rem;
    border-bottom: 1px solid var(--line-strong);
  }
  .panel-kicker {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
  }
  .panel-title {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 1.08rem;
    font-weight: 700;
    color: var(--ink);
    margin-top: 0.25rem;
  }

  /* Macro Dashboard Strip (GDP, Unemployment, Recession Odds) */
  .macro-vitals-strip {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.25rem;
    margin: 2.25rem 0;
  }
  .vital-box {
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-top: 3px solid var(--slate-blue);
    padding: 1.25rem;
  }
  .vital-tag {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 0.4rem;
  }
  .vital-figure {
    font-family: 'JetBrains Mono', monospace;
    font-size: 1.65rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.35rem;
  }
  .vital-desc {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    color: var(--muted);
    line-height: 1.45;
  }

  /* Counter-Argument Dossier (p17-p19) */
  .counter-view-dossier {
    margin: 3rem 0 2.5rem;
    background: var(--dissent-bg);
    border: 1px solid var(--line-strong);
    border-left: 5px solid var(--slate-blue);
    padding: 2.25rem 2rem;
  }
  .dissent-header {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--line-strong);
  }
  .dissent-badge {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    background: var(--slate-blue);
    color: #fff;
    padding: 0.28rem 0.65rem;
    border-radius: 2px;
  }
  .dissent-economist {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.86rem;
    font-weight: 600;
    color: var(--muted);
  }
  .dissent-quote-highlight {
    margin-top: 1.25rem;
    padding: 1.25rem 1.5rem;
    background: var(--paper);
    border-left: 3px solid var(--slate-blue);
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.15rem;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.75;
  }

  /* Source Graphics Index Note (p20) */
  .archive-graphics-note {
    margin-top: 2.5rem;
    padding: 1.35rem 1.5rem;
    background: var(--paper-subtle);
    border: 1px dashed var(--line-strong);
    border-radius: 3px;
  }
  .archive-graphics-label {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    margin-bottom: 0.45rem;
  }
  .archive-graphics-note .prose-p {
    font-family: 'Inter', 'Noto Sans SC', sans-serif !important;
    font-size: 0.84rem !important;
    line-height: 1.65 !important;
    color: var(--muted);
    margin-bottom: 0;
  }

  /* Footer */
  .editorial-footer {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2rem 1.5rem 4rem;
    border-top: 1px solid var(--line-strong);
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 1rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.8rem;
    color: var(--muted);
  }

  /* Mobile Reflow (390px and tablets) */
  @media (max-width: 960px) {
    .editorial-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .sidebar-rail {
      position: static;
    }
    .metrics-trio,
    .macro-vitals-strip {
      grid-template-columns: 1fr;
    }
    .quant-showcase {
      padding: 1.65rem 1.15rem;
    }
    .counter-view-dossier {
      padding: 1.5rem 1.2rem;
    }
  }

  @media (max-width: 520px) {
    .masthead {
      padding: 0.65rem 1rem;
    }
    .edition-meta {
      display: none;
    }
    .hero-header,
    .article-shell {
      padding-left: 1.1rem;
      padding-right: 1.1rem;
    }
    .prose-p {
      font-size: 1.05rem;
    }
    .lead-p {
      font-size: 1.13rem !important;
    }
  }
